function reveal(){if(reduced)return;const ob=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');ob.unobserve(e.target)}}),{threshold:.11});$$('.reveal').forEach(el=>ob.observe(el))}
let lightboxPhotos=[],lightboxIndex=-1,lightboxReturn=null;
function lightbox(){const modal=$('#lightbox'),close=$('#lightboxClose');function shut(){modal.hidden=true;document.body.classList.remove('lock');lightboxReturn?.focus();}close.addEventListener('click',shut);modal.addEventListener('click',e=>{if(e.target===modal)shut()});document.addEventListener('keydown',e=>{if(modal.hidden)return;if(e.key==='Escape'){e.preventDefault();shut()}else if(e.key==='ArrowRight')navigateLightbox(1);else if(e.key==='ArrowLeft')navigateLightbox(-1);else if(e.key==='Tab'){const actions=$$('button:not([disabled])',modal);const idx=actions.indexOf(document.activeElement);if(e.shiftKey&&idx===0){e.preventDefault();actions[actions.length-1].focus()}else if(!e.shiftKey&&idx===actions.length-1){e.preventDefault();actions[0].focus()}}});$('#lightboxPrev').onclick=()=>navigateLightbox(-1);$('#lightboxNext').onclick=()=>navigateLightbox(1)}
function navigateLightbox(dir){if(!lightboxPhotos.length)return;lightboxIndex=(lightboxIndex+dir+lightboxPhotos.length)%lightboxPhotos.length;const p=lightboxPhotos[lightboxIndex];$('#lightboxImage').src=p.path;$('#lightboxImage').alt=p.caption;$('#lightboxCaption').textContent=`${String(lightboxIndex+1).padStart(2,'0')} / ${lightboxPhotos.length} — ${p.caption}`}
function openLightbox(src,caption,photos=[],index=-1){lightboxReturn=document.activeElement;lightboxPhotos=photos;lightboxIndex=index;$('#lightboxImage').src=src;$('#lightboxImage').alt=caption;$('#lightboxCaption').textContent=photos.length?`${index+1} / ${photos.length} — ${caption}`:caption;const hasMany=photos.length>1;$('#lightboxPrev').hidden=!hasMany;$('#lightboxNext').hidden=!hasMany;$('#lightbox').hidden=false;document.body.classList.add('lock');$('#lightboxClose').focus()}
